Module[{previous = VVMFToolConfiguration[], directory = AbsoluteFileName[CreateDirectory[]],
  g, h, file, restored, subgroups, before, afterEviction, result, ids},
 WithCleanup[
  ConfigureVVMFTool[CacheDirectory -> FileNameJoin[{directory, "cache"}],
   CoreBudget -> 1, ProgressFunction -> None],
  result = Catch[
   g = BuildModularGroup["24-3I"];
   If[FailureQ[g], Throw[g]];
   file = SaveGroupData[g, FileNameJoin[{directory, "group.json"}]];
   If[FailureQ[file], Throw[file]];
   h = ImportGroupData[file];
   If[FailureQ[h], Throw[h]];
   restored = RestoreGAPState[h];
   If[FailureQ[restored], Throw[restored]];
   subgroups = GroupSubgroups[h, SubgroupKind -> "Normal", SubgroupOrder -> 8];
   If[FailureQ[subgroups], Throw[subgroups]];
   before = h["CharacterData"];
   CleanGAPCache["All"];
   afterEviction = GroupWordOrder[h, GroupWord[{}]];
   If[FailureQ[afterEviction], Throw[afterEviction]];
   ids = h["IrrepOrder"];
   {h["Order"], NumberOfRep[h], h =!= g, restored["Restored"],
    subgroups["Complete"], Length[subgroups["Items"]], afterEviction,
    h["CharacterData"] === before,
    AllTrue[ids, GroupRepresentation[h, #] === GroupRepresentation[g, #] &],
    AllTrue[ids, UnitaryRepresentationQ[GroupRepresentation[h, #]] &&
      DiagonalMatrixQ[TRep[h, GroupRepresentation[h, #]]] &]}],
  CleanGAPCache["All"];
  ConfigureVVMFTool[Sequence @@ Normal[previous]];
  DeleteDirectory[directory, DeleteContents -> True]];
 result]
